"use client";

import { useId, useState } from "react";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import {
  QUOTE_RANGES,
  RANGE_LABEL,
  formatPrice,
  quoteLogoUrl,
  summarizeQuote,
} from "@/features/quote/quote-schema";
import type { QuoteData, QuoteRange } from "@/features/quote/quote-schema";

export type QuoteCardState = "streaming" | "loading" | "ready" | "error";

export interface QuoteCardProps {
  readonly state: QuoteCardState;
  /**
  The ticker from the tool input, shown before the data arrives.
  */
  readonly ticker?: string;
  readonly data?: QuoteData;
  readonly error?: string;
  /**
  Loads another range when the reader switches it. Without it, the switch is hidden and the card shows the range it was given.
  */
  readonly loadRange?: (
    ticker: string,
    range: QuoteRange
  ) => Promise<QuoteData>;
  /**
  Shows when the price was taken. Turn it off for saved data, where the time is the save date, not the reader's now.
  */
  readonly showAsOf?: boolean;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-sm`;

export const QuoteCard = ({
  state,
  ticker,
  data,
  error,
  loadRange,
  showAsOf = true,
  className,
}: QuoteCardProps) => {
  const [override, setOverride] = useState<QuoteData | null>(null);
  const [pendingRange, setPendingRange] = useState<QuoteRange | null>(null);
  const [rangeError, setRangeError] = useState<string | null>(null);
  const shown = override ?? data;

  const selectRange = async (range: QuoteRange) => {
    if (!(loadRange && shown) || range === shown.range) {
      return;
    }
    setPendingRange(range);
    setRangeError(null);
    try {
      setOverride(await loadRange(shown.ticker, range));
    } catch {
      setRangeError("Couldn't load that range.");
    } finally {
      setPendingRange(null);
    }
  };

  if (!(state === "error" || (state === "ready" && shown))) {
    return (
      <QuoteCardSkeleton
        ticker={ticker}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  if (state === "error" || !shown) {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <QuoteError ticker={ticker} message={error} />
      </div>
    );
  }
  return (
    <section
      aria-label={summarizeQuote(shown)}
      className={cn(CARD_FRAME, className)}
    >
      <QuoteReady
        data={shown}
        pendingRange={pendingRange}
        rangeError={rangeError}
        showAsOf={showAsOf}
        onSelectRange={loadRange ? selectRange : undefined}
      />
    </section>
  );
};

const QuoteReady = ({
  data,
  pendingRange,
  rangeError,
  showAsOf,
  onSelectRange,
}: {
  readonly data: QuoteData;
  readonly pendingRange: QuoteRange | null;
  readonly rangeError: string | null;
  readonly showAsOf: boolean;
  readonly onSelectRange?: (range: QuoteRange) => void;
}) => {
  const isUp = data.change >= 0;
  const sign = isUp ? "+" : "−";
  const tone = isUp
    ? "text-emerald-600 dark:text-emerald-400"
    : "text-red-600 dark:text-red-400";

  return (
    <div className="flex flex-col gap-3">
      <header className="flex items-start justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <QuoteLogo ticker={data.ticker} />
          <div className="min-w-0">
            <p className="text-sm font-semibold">{data.ticker}</p>
            <p className="text-muted-foreground truncate text-xs">
              {data.name}
              {data.exchange ? ` · ${data.exchange}` : ""}
            </p>
          </div>
        </div>
        {data.fake ? (
          <span className="text-muted-foreground rounded-md border px-1.5 py-0.5 text-[11px]">
            Demo data
          </span>
        ) : null}
      </header>

      <div className="flex items-baseline gap-2">
        <p className="text-2xl font-semibold tabular-nums">
          {formatPrice(data.price, data.currency)}
        </p>
        <p className={cn("text-sm font-medium tabular-nums", tone)}>
          {sign}
          {formatPrice(Math.abs(data.change), data.currency)} ({sign}
          {Math.abs(data.changePercent).toFixed(2)}%)
        </p>
      </div>

      <div
        className={cn(
          "transition-opacity duration-150",
          pendingRange && "opacity-40"
        )}
      >
        <Sparkline data={data} className={tone} />
      </div>

      <div className="flex items-center justify-between gap-2">
        {onSelectRange ? (
          <div
            role="group"
            aria-label="Range"
            className="bg-muted flex gap-0.5 rounded-lg p-0.5"
          >
            {QUOTE_RANGES.map((range) => {
              const isSelected = (pendingRange ?? data.range) === range;
              return (
                <button
                  key={range}
                  type="button"
                  aria-pressed={isSelected}
                  onClick={() => onSelectRange(range)}
                  className={cn(
                    "focus-visible:ring-ring rounded-md px-2 py-0.5 text-xs font-medium transition-colors outline-none focus-visible:ring-2",
                    isSelected
                      ? "bg-background text-foreground shadow-sm"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  {RANGE_LABEL[range]}
                </button>
              );
            })}
          </div>
        ) : (
          <span className="text-muted-foreground text-xs">
            {RANGE_LABEL[data.range]}
          </span>
        )}
        <p className="text-muted-foreground text-xs" aria-live="polite">
          {rangeError ?? (showAsOf ? `As of ${formatTime(data.asOf)}` : null)}
        </p>
      </div>
    </div>
  );
};

const Sparkline = ({
  data,
  className,
}: {
  readonly data: QuoteData;
  readonly className?: string;
}) => {
  const gradientId = useId();
  const [active, setActive] = useState<number | null>(null);
  const width = 300;
  const height = 64;
  const { points } = data;
  if (points.length < 2) {
    return <div className="h-16" />;
  }
  const prices = points.map((point) => point.price);
  const min = Math.min(...prices);
  const max = Math.max(...prices);
  const span = max - min || 1;
  const coords = prices.map((price, index) => [
    (index / (prices.length - 1)) * width,
    height - 2 - ((price - min) / span) * (height - 4),
  ]);
  const line = coords
    .map(
      ([x, y], index) =>
        `${index === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`
    )
    .join(" ");

  const last = points.length - 1;
  const indexAt = (clientX: number, box: DOMRect) =>
    Math.round(
      Math.min(Math.max((clientX - box.left) / box.width, 0), 1) * last
    );

  const point = active === null ? null : points[active];
  const xPercent = active === null ? 0 : (active / last) * 100;
  const yPercent = active === null ? 0 : (coords[active][1] / height) * 100;
  const labelAlign =
    xPercent < 20
      ? "translate-x-0"
      : xPercent > 80
        ? "-translate-x-full"
        : "-translate-x-1/2";

  return (
    <div
      tabIndex={0}
      role="img"
      aria-label={
        point
          ? `${formatPrice(point.price, data.currency)} at ${formatPointTime(point.time, data.range)}`
          : summarizeQuote(data)
      }
      onPointerMove={(event) =>
        setActive(
          indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
        )
      }
      onPointerDown={(event) =>
        setActive(
          indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
        )
      }
      onPointerLeave={() => setActive(null)}
      onFocus={() => setActive((current) => current ?? last)}
      onBlur={() => setActive(null)}
      onKeyDown={(event) => {
        if (!(event.key === "ArrowLeft" || event.key === "ArrowRight")) {
          return;
        }

        event.preventDefault();
        const step = event.key === "ArrowLeft" ? -1 : 1;
        setActive((current) =>
          Math.min(Math.max((current ?? last) + step, 0), last)
        );
      }}
      className={cn(
        "focus-visible:ring-ring relative h-16 w-full cursor-crosshair touch-pan-y rounded outline-none focus-visible:ring-2",
        className
      )}
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        aria-hidden
        className="size-full"
      >
        <defs>
          <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="currentColor" stopOpacity={0.18} />
            <stop offset="100%" stopColor="currentColor" stopOpacity={0} />
          </linearGradient>
        </defs>
        <path
          d={`${line} L${width},${height} L0,${height} Z`}
          fill={`url(#${gradientId})`}
        />
        <path
          d={line}
          fill="none"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>

      {point ? (
        <>
          <div
            aria-hidden
            className="bg-border pointer-events-none absolute inset-y-0 w-px"
            style={{ left: `${xPercent}%` }}
          />
          <div
            aria-hidden
            className="ring-card pointer-events-none absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-current ring-2"
            style={{ left: `${xPercent}%`, top: `${yPercent}%` }}
          />
          <div
            aria-hidden
            className={cn(
              "bg-popover text-popover-foreground pointer-events-none absolute top-0 rounded-md border px-2 py-1 text-xs whitespace-nowrap shadow-sm",
              labelAlign
            )}
            style={{ left: `${xPercent}%` }}
          >
            <span className="font-semibold tabular-nums">
              {formatPrice(point.price, data.currency)}
            </span>
            <span className="text-muted-foreground ml-2 tabular-nums">
              {formatPointTime(point.time, data.range)}
            </span>
          </div>
        </>
      ) : null}
    </div>
  );
};

function formatPointTime(time: number, range: QuoteRange) {
  const date = new Date(time);
  if (range === "1d") {
    return date.toLocaleTimeString("en-US", {
      hour: "numeric",
      minute: "2-digit",
    });
  }
  if (range === "1w") {
    return date.toLocaleString("en-US", {
      hour: "numeric",
      minute: "2-digit",
      weekday: "short",
    });
  }
  return date.toLocaleDateString("en-US", {
    day: "numeric",
    month: "short",
    ...(range === "1y" && { year: "numeric" }),
  });
}

const QuoteLogo = ({ ticker }: { readonly ticker: string }) => {
  const [failed, setFailed] = useState(false);
  if (failed) {
    return (
      <div
        aria-hidden
        className="bg-muted text-muted-foreground flex size-9 shrink-0 items-center justify-center rounded-lg text-sm font-semibold"
      >
        {ticker.charAt(0)}
      </div>
    );
  }
  return (
    // eslint-disable-next-line @next/next/no-img-element -- next/image would force the logo host into the installer's next.config
    <img
      src={quoteLogoUrl(ticker)}
      alt=""
      width={36}
      height={36}
      loading="lazy"
      onError={() => setFailed(true)}
      className="size-9 shrink-0 rounded-lg object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10"
    />
  );
};

const QuoteError = ({
  ticker,
  message,
}: {
  readonly ticker?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {ticker
        ? `Couldn't load ${ticker.toUpperCase()}`
        : "Couldn't load the quote"}
    </p>
    <p className="text-muted-foreground text-xs">
      {message ?? "The quote service didn't respond. Try again in a moment."}
    </p>
  </div>
);

function formatTime(time: number) {
  return new Date(time).toLocaleString("en-US", {
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    month: "short",
  });
}

/** The card while its data is on the way: the same frame and rows as the
 *  ready card, so nothing moves when the quote lands. Shows the ticker as
 *  soon as it's known (with "…" while the model is still writing it). */
export const QuoteCardSkeleton = ({
  ticker,
  streaming = false,
  className,
}: {
  readonly ticker?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <div
    className={cn(CARD_FRAME, "flex flex-col gap-3", className)}
    role="status"
  >
    <span className="sr-only">
      {ticker ? `Loading the quote for ${ticker}` : "Loading a quote"}
    </span>
    <div aria-hidden className="flex items-center gap-3">
      <div className="bg-muted size-9 shrink-0 animate-pulse rounded-lg" />
      <div className="flex flex-col">
        {ticker ? (
          <p className="text-sm font-semibold">
            {ticker.toUpperCase()}
            {streaming ? (
              <span className="text-muted-foreground">…</span>
            ) : null}
          </p>
        ) : (
          <div className="flex h-5 items-center">
            <div className="bg-muted h-3.5 w-14 animate-pulse rounded" />
          </div>
        )}
        <div className="flex h-4 items-center">
          <div className="bg-muted h-3 w-32 animate-pulse rounded" />
        </div>
      </div>
    </div>
    <div aria-hidden className="bg-muted h-8 w-40 animate-pulse rounded" />
    <div aria-hidden className="bg-muted h-16 w-full animate-pulse rounded" />
    <div aria-hidden className="bg-muted h-6 w-36 animate-pulse rounded-lg" />
  </div>
);

"use client";

import { useEffect, useState } from "react";
import { QuoteCard } from "@/features/quote/components/quote-card";
import { loadQuote } from "@/features/quote/quote-requests";
import type { QuoteData, QuoteRange } from "@/features/quote/quote-schema";

type Load =
  | { status: "loading" }
  | { status: "ready"; data: QuoteData }
  | { status: "error"; message: string };

export const LiveQuoteCard = ({
  ticker,
  range = "1d",
  streaming = false,
}: {
  readonly ticker?: string;
  readonly range?: QuoteRange;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [load, setLoad] = useState<Load>({ status: "loading" });

  useEffect(() => {
    if (streaming || !ticker) {
      return;
    }
    let isCancelled = false;
    setLoad({ status: "loading" });
    const run = async () => {
      try {
        const data = await loadQuote(ticker, range);
        if (!isCancelled) {
          setLoad({ data, status: "ready" });
        }
      } catch (error) {
        if (!isCancelled) {
          setLoad({
            message: Error.isError(error) ? error.message : "Quote failed.",
            status: "error",
          });
        }
      }
    };
    run();
    return () => {
      isCancelled = true;
    };
  }, [ticker, range, streaming]);

  if (streaming || !ticker) {
    return <QuoteCard state="streaming" ticker={ticker} />;
  }
  if (load.status === "ready") {
    return <QuoteCard state="ready" data={load.data} loadRange={loadQuote} />;
  }
  return load.status === "error" ? (
    <QuoteCard state="error" ticker={ticker} error={load.message} />
  ) : (
    <QuoteCard state="loading" ticker={ticker} />
  );
};

import { z } from "zod";
import { QUOTE_RANGES } from "@/features/quote/quote-schema";

export const quoteCatalogEntry = {
  description:
    "A live stock quote card: current price, change, a small trend line and a 1D/1W/1M/1Y switch. It fetches its own data. Use it whenever the user asks how a stock, ETF or company's shares are doing. Convert company names to their ticker.",
  props: z.object({
    range: z
      .enum(QUOTE_RANGES)
      .nullable()
      .describe(
        "Trend line range: 1d (today), 1w, 1m or 1y. Null for today, unless the user asks about a longer period."
      ),
    ticker: z.string().describe("The ticker symbol, for example NVDA."),
  }),
};

import type { QuoteData, QuoteRange } from "@/features/quote/quote-schema";

const sharedQuoteRequests = new Map<
  string,
  { expiresAt: number; quote: Promise<QuoteData> }
>();
const REUSE_MS = 60_000;

function quoteKey(ticker: string, range: QuoteRange) {
  return `${ticker.toUpperCase()}:${range}`;
}

async function fetchQuote(ticker: string, range: QuoteRange) {
  const response = await fetch(
    `/api/quote?ticker=${encodeURIComponent(ticker)}&range=${range}`
  );
  const body = (await response.json()) as QuoteData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body ? body.error : `Quote request failed: ${response.status}`
    );
  }
  return body;
}

async function requestQuote(key: string, ticker: string, range: QuoteRange) {
  try {
    return await fetchQuote(ticker, range);
  } catch (error) {
    sharedQuoteRequests.delete(key);
    throw error;
  }
}

export function loadQuote(ticker: string, range: QuoteRange) {
  const key = quoteKey(ticker, range);
  const hit = sharedQuoteRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.quote;
  }
  const quote = requestQuote(key, ticker, range);
  sharedQuoteRequests.set(key, { expiresAt: Date.now() + REUSE_MS, quote });
  return quote;
}

export function primeQuote(ticker: string, range: QuoteRange, data: QuoteData) {
  sharedQuoteRequests.set(quoteKey(ticker, range), {
    expiresAt: Infinity,
    quote: Promise.resolve(data),
  });
}

import { loadQuote } from "@/features/quote/quote-requests";
import { listOf } from "@/features/chat/lookup";
import type { CardLookup } from "@/features/chat/lookup";
import type { QuoteRange } from "@/features/quote/quote-schema";

function propertiesOf(properties: Record<string, unknown>) {
  return {
    range: (properties.range ?? "1d") as QuoteRange,
    ticker: typeof properties.ticker === "string" ? properties.ticker : "",
  };
}

export const quoteLookup: CardLookup = {
  intent: (tickers) =>
    tickers.length === 1
      ? `A stock quote for ${tickers[0]}`
      : `Stock quotes for ${listOf(tickers)}`,
  load: (properties) => {
    const { ticker, range } = propertiesOf(properties);
    return loadQuote(ticker, range);
  },
  sources: (properties) => {
    const ticker = propertiesOf(properties).ticker.trim().toUpperCase();
    return [
      {
        href: `https://finance.yahoo.com/quote/${encodeURIComponent(ticker)}`,
        label: `finance.yahoo.com/quote/${ticker}`,
      },
    ];
  },
  subject: (properties) =>
    propertiesOf(properties).ticker.trim().toUpperCase() || null,
};

import "server-only";
import type {
  QuoteData,
  QuotePoint,
  QuoteRange,
} from "@/features/quote/quote-schema";

// Server only: the endpoint doesn't allow browser requests (CORS).

const YAHOO_RANGE: Record<QuoteRange, { range: string; interval: string }> = {
  "1d": { interval: "5m", range: "1d" },
  "1m": { interval: "1d", range: "1mo" },
  "1w": { interval: "30m", range: "5d" },
  "1y": { interval: "1wk", range: "1y" },
};

interface YahooChart {
  chart: {
    result:
      | {
          meta: {
            symbol: string;
            currency?: string;
            longName?: string;
            shortName?: string;
            fullExchangeName?: string;
            exchangeName?: string;
            regularMarketPrice: number;
            regularMarketTime: number;
            chartPreviousClose?: number;
            previousClose?: number;
          };
          timestamp?: number[];
          indicators: { quote: { close: (number | null)[] }[] };
        }[]
      | null;
    error: { code: string; description: string } | null;
  };
}

export class QuoteNotFoundError extends Error {
  constructor(ticker: string, options?: ErrorOptions) {
    super(`No quote found for "${ticker}".`, options);
    this.name = "QuoteNotFoundError";
  }
}

/**
The live quote for a ticker. Pass it normalized (trimmed, upper case).
*/
export async function getQuote(
  ticker: string,
  range: QuoteRange = "1d"
): Promise<QuoteData> {
  const { range: yahooRange, interval } = YAHOO_RANGE[range];
  const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(ticker)}?range=${yahooRange}&interval=${interval}`;

  const response = await fetch(url);
  if (response.status === 404) {
    throw new QuoteNotFoundError(ticker);
  }
  if (!response.ok) {
    throw new Error(`The quote service returned ${response.status}.`);
  }

  const body = (await response.json()) as YahooChart;
  const result = body.chart.result?.[0];
  if (!result) {
    throw new QuoteNotFoundError(ticker);
  }

  const { meta } = result;
  const closes = result.indicators.quote[0]?.close ?? [];
  const points: QuotePoint[] = (result.timestamp ?? []).flatMap(
    (time, index) => {
      const price = closes[index];
      return price == null ? [] : [{ price, time: time * 1000 }];
    }
  );

  const price = meta.regularMarketPrice;
  const base =
    range === "1d"
      ? (meta.chartPreviousClose ?? meta.previousClose ?? points[0]?.price)
      : points[0]?.price;
  const change = base === undefined ? 0 : price - base;

  return {
    asOf: meta.regularMarketTime * 1000,
    change,
    changePercent: base ? (change / base) * 100 : 0,
    currency: meta.currency ?? "USD",
    exchange: meta.fullExchangeName ?? meta.exchangeName ?? "",
    fake: false,
    name: meta.longName ?? meta.shortName ?? meta.symbol,
    points,
    price,
    range,
    ticker: meta.symbol,
  };
}

import { z } from "zod";

export const QUOTE_RANGES = ["1d", "1w", "1m", "1y"] as const;
export type QuoteRange = (typeof QUOTE_RANGES)[number];

export const RANGE_LABEL: Record<QuoteRange, string> = {
  "1d": "1D",
  "1m": "1M",
  "1w": "1W",
  "1y": "1Y",
};

/**
What the model sends: the tool's input.
*/
export const quoteInputSchema = z.object({
  range: z
    .enum(QUOTE_RANGES)
    .default("1d")
    .describe(
      "The time range for the trend line: 1d (today), 1w, 1m or 1y. Use 1d unless the user asks about a longer period."
    ),
  ticker: z
    .string()
    .min(1)
    .max(10)
    .describe(
      "The stock or ETF ticker symbol, for example NVDA or AAPL. Convert company names to their ticker."
    ),
});
export type QuoteInput = z.infer<typeof quoteInputSchema>;

export interface QuotePoint {
  /**
  Unix time in milliseconds.
  */
  time: number;
  price: number;
}

export interface QuoteData {
  ticker: string;
  name: string;
  /**
  e.g. "USD".
  */
  currency: string;
  exchange: string;
  range: QuoteRange;
  price: number;
  /**
  Change over the range: against the previous close for 1d, against the first point otherwise.
  */
  change: number;
  changePercent: number;
  points: QuotePoint[];
  /**
  Unix time in milliseconds of the latest price.
  */
  asOf: number;
  /**
  True when this is generated data, not a live quote.
  */
  fake: boolean;
}

/**
The company's logo: a square tile from Parqet's public logo CDN, by ticker, no API key. A ticker without one answers 404, and the card falls back to a letter tile.
*/
export function quoteLogoUrl(ticker: string): string {
  return `https://assets.parqet.com/logos/symbol/${encodeURIComponent(ticker.toUpperCase())}?format=png`;
}

/** One sentence the model (or a screen reader) can use to describe the
 *  card. */
export function summarizeQuote(data: QuoteData): string {
  const price = formatPrice(data.price, data.currency);
  const direction = data.change >= 0 ? "up" : "down";
  const percent = `${Math.abs(data.changePercent).toFixed(2)}%`;
  const period =
    data.range === "1d"
      ? "today"
      : `over the past ${{ "1m": "month", "1w": "week", "1y": "year" }[data.range]}`;
  return `${data.name} (${data.ticker}) is at ${price}, ${direction} ${percent} ${period}.`;
}

export function formatPrice(value: number, currency: string): string {
  try {
    return new Intl.NumberFormat("en-US", {
      currency,
      maximumFractionDigits: 2,
      minimumFractionDigits: 2,
      style: "currency",
    }).format(value);
  } catch {
    return `${value.toFixed(2)} ${currency}`;
  }
}

import type { QuoteData, QuoteRange } from "@/features/quote/quote-schema";

const STEPS: Record<QuoteRange, { count: number; every: number }> = {
  "1d": { count: 78, every: 5 * 60_000 },
  "1m": { count: 22, every: 86_400_000 },
  "1w": { count: 65, every: 30 * 60_000 },
  "1y": { count: 52, every: 7 * 86_400_000 },
};

function seeded(seed: string) {
  let state = 0;
  for (const char of seed) {
    state = Math.imul(state ^ (char.codePointAt(0) ?? 0), 2_654_435_761);
  }
  return () => {
    state = Math.imul(state ^ (state >>> 15), 2_246_822_507);
    state = Math.imul(state ^ (state >>> 13), 3_266_489_909);
    return ((state ^= state >>> 16) >>> 0) / 4_294_967_296;
  };
}

export function fakeQuote(
  ticker: string,
  range: QuoteRange = "1d",
  now = Date.UTC(2026, 9, 14, 20, 0)
): QuoteData {
  const symbol = ticker.trim().toUpperCase();
  const random = seeded(`${symbol}:${range}`);
  const { count, every } = STEPS[range];

  let price = 50 + random() * 400;
  const points = Array.from({ length: count }, (_, index) => {
    price *= 1 + (random() - 0.5) * 0.02;
    return { price, time: now - (count - 1 - index) * every };
  });

  const first = points[0].price;
  const last = points.at(-1)?.price ?? first;
  return {
    asOf: now,
    change: last - first,
    changePercent: ((last - first) / first) * 100,
    currency: "USD",
    exchange: "Demo",
    fake: true,
    name: `${symbol} Inc.`,
    points,
    price: last,
    range,
    ticker: symbol,
  };
}

import { getQuote, QuoteNotFoundError } from "@/features/quote/quote-queries";
import { QUOTE_RANGES } from "@/features/quote/quote-schema";
import type { QuoteRange } from "@/features/quote/quote-schema";

const CACHE = "public, s-maxage=60, stale-while-revalidate=300";

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const ticker = searchParams.get("ticker")?.trim().toUpperCase();
  const range = searchParams.get("range") ?? "1d";

  if (!ticker || !(QUOTE_RANGES as readonly string[]).includes(range)) {
    return Response.json(
      { error: "Pass a ticker and a range of 1d, 1w, 1m or 1y." },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getQuote(ticker, range as QuoteRange), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status = error instanceof QuoteNotFoundError ? 404 : 502;
    return Response.json(
      { error: Error.isError(error) ? error.message : "Quote failed." },
      { status }
    );
  }
}

